42	pub(crate) fn try_call(
43	    name: &str,
44	    args: Vec<DenseArray>,
45	) -> Option<Result<DenseArray, RuntimeError>> {
46	    match name {
47	        "pi" => Some(zero_arg(name, args, std::f64::consts::PI)),
48	        "e" => Some(zero_arg(name, args, std::f64::consts::E)),
49	        "exp" => Some(unary(name, args, f64::exp)),
50	        "log" => Some(unary(name, args, f64::ln)),
51	        "sqrt" => Some(unary(name, args, f64::sqrt)),
52	        "abs" => Some(unary(name, args, f64::abs)),
53	        "sin" => Some(unary(name, args, f64::sin)),
54	        "cos" => Some(unary(name, args, f64::cos)),
55	        "sigmoid" => Some(unary(name, args, |x| 1.0 / (1.0 + (-x).exp()))),
56	        "tanh_fn" => Some(unary(name, args, f64::tanh)),
57	        "relu" => Some(unary(name, args, |x| x.max(0.0))),
58	        "floor" => Some(unary(name, args, f64::floor)),
59	        "ceil" => Some(unary(name, args, f64::ceil)),
60	        "round" => Some(unary(name, args, f64::round)),
61	        "pow" => Some(binary_pow(name, args)),
62	        "mod" => Some(binary_cmp(name, args, |a, b| a % b)),
63	        "gt" => Some(binary_cmp(name, args, |a, b| if a > b { 1.0 } else { 0.0 })),
64	        "lt" => Some(binary_cmp(name, args, |a, b| if a < b { 1.0 } else { 0.0 })),
65	        "eq" => Some(binary_cmp(name, args, |a, b| {
66	            if (a - b).abs() < f64::EPSILON {
67	                1.0
68	            } else {
69	                0.0
70	            }
71	        })),
72	        "mean" => Some(builtin_mean(name, args)),
73	        "zeros" | "ones" | "fill" => Some(constructor(name, args)),
74	        "cosine_schedule" | "linear_warmup" => Some(schedule(name, args)),
75	        // Saga 29 step 005: the 2-arg `concat(a, b)` is the
76	        // original Saga 13 generation-loop helper for rank-0/1
77	        // arrays. The new 3-arg `concat(a, b, axis)` is the
78	        // tape-differentiable axis-aware form, dispatched by
79	        // `builtins.rs` -- let it fall through here.
80	        "concat" if args.len() != 3 => Some(array_util(name, args)),
81	        "last_row" => Some(array_util(name, args)),
82	        _ => None,
83	    }
84	}
