138	    pub(crate) fn parse_def(&mut self) -> Result<Expr, ParseError> {
139	        let start = self.tokens[self.pos].span;
140	        self.pos += 1; // skip 'def'
141	        let tok = &self.tokens[self.pos];
142	        let TokenKind::Ident(ns) = &tok.kind else {
