214	            self.skip_sep();
215	        }
216	        if !self.is(TokenKind::RBrace) {
217	            return Err(ParseError::UnclosedDelimiter {
218	                open: "{".into(),
219	                span: open,
220	            });
221	        }
222	        let end = self.tokens[self.pos].span;
223	        self.pos += 1;
224	        Ok((body, end))
225	    }
226	}
