    id: &[f64],
    fd: &[f64],
    p: &Params,
    bi: usize,
    co: usize,
    oh: usize,
    ow: usize,
) -> f64 {
    let mut sum = 0.0;
    for ci in 0..p.c_in {
        for fh in 0..p.kh {
            for fw in 0..p.kw {
                let ih = (oh * p.stride + fh) as isize - p.padding as isize;
