use mlpl_array::{DenseArray, Shape};
use mlpl_runtime_core::error::RuntimeError;

struct Params {
    b: usize,
    c: usize,
    h: usize,
    w: usize,
    ph: usize,
    pw: usize,
    h_out: usize,
    w_out: usize,
    is_max: bool,
}

pub(crate) fn run(args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
    if args.len() != 3 {
        return Err(RuntimeError::ArityMismatch {
            func: "pool2d".into(),
            expected: 3,
            got: args.len(),
        });
    }
    let p = validate(&args)?;
    let out = compute(args[0].data(), &p);
    Ok(DenseArray::new(
        Shape::new(vec![p.b, p.c, p.h_out, p.w_out]),
        out,
    )?)
}

fn validate(args: &[DenseArray]) -> Result<Params, RuntimeError> {
    let id = args[0].shape().dims();
    if id.len() != 4 {
        return Err(RuntimeError::InvalidArgument {
            func: "pool2d".into(),
            reason: format!(
                "input must be [B,C,H,W], got rank {}",
                id.len()
            ),
        });
    }
    let sd = args[1].data();
    if sd.len() != 2 {
        return Err(RuntimeError::InvalidArgument {
            func: "pool2d".into(),
            reason: format!(
                "size must be [pH, pW], got {} elements",
                sd.len()
            ),
        });
    }
    let mode_val = args[2].data();
    Ok(Params {
        b: id[0],
        c: id[1],
        h: id[2],
        w: id[3],
        ph: sd[0] as usize,
        pw: sd[1] as usize,
        h_out: id[2] / sd[0] as usize,
        w_out: id[3] / sd[1] as usize,
        is_max: mode_val.first().copied().unwrap_or(0.0) != 0.0,
    })
}

fn compute(idata: &[f64], p: &Params) -> Vec<f64> {
    let mut out = vec![0.0f64; p.b * p.c * p.h_out * p.w_out];
    for bi in 0..p.b {
        for ci in 0..p.c {
            for oh in 0..p.h_out {
                for ow in 0..p.w_out {
                    let val = pool_window(idata, p, bi, ci, oh, ow);
                    out[bi * p.c * p.h_out * p.w_out
                        + ci * p.h_out * p.w_out
                        + oh * p.w_out
                        + ow] = val;
                }
            }
        }
    }
    out
}

fn pool_window(
    idata: &[f64],
    p: &Params,
    bi: usize,
    ci: usize,
    oh: usize,
    ow: usize,
) -> f64 {
    let mut val = if p.is_max { f64::NEG_INFINITY } else { 0.0 };
    for fh in 0..p.ph {
        for fw in 0..p.pw {
            let v = idata[bi * p.c * p.h * p.w
                + ci * p.h * p.w
                + (oh * p.ph + fh) * p.w
                + ow * p.pw
                + fw];
            if p.is_max {
                val = val.max(v);
            } else {
                val += v;
            }
        }
    }
    if !p.is_max {
        val /= (p.ph * p.pw) as f64;
    }
    val
}

