16	/// Dispatch ML built-ins. Returns None if not matched.
17	pub(crate) fn try_call(
18	    name: &str,
19	    args: Vec<DenseArray>,
20	) -> Option<Result<DenseArray, RuntimeError>> {
21	    match name {
22	        "softmax" => Some(builtin_softmax(name, args)),
23	        "one_hot" => Some(builtin_one_hot(name, args)),
24	        "sinusoidal_encoding" => Some(builtin_sinusoidal_encoding(name, args)),
25	        "cross_entropy" => Some(builtin_cross_entropy(name, args)),
26	        // Perplexity is `exp(cross_entropy(...))` -- inlined here
27	        // rather than extracted to a sibling fn so the module's
28	        // function count stays at 7 (sw-checklist max).
29	        "perplexity" => Some(
30	            builtin_cross_entropy(name, args).map(|ce| DenseArray::from_scalar(ce.data()[0].exp())),
31	        ),
32	        _ => None,
33	    }
34	}
