use mlpl_array::{ArrayError, DenseArray, Shape};

use crate::labels::matmul_labels;

/// Matrix-multiplication extension for `DenseArray`. Bring into
/// scope with `use mlpl_array_ops_matmul::prelude::*;` to call
/// `a.matmul(&b)`.
pub trait MatmulExt {
    /// Matrix multiplication:
    /// - `[m, k] * [k, n] -> [m, n]`
    /// - `[m, k] * [k]    -> [m]`  (matrix-vector product)
    fn matmul(&self, other: &DenseArray) -> Result<DenseArray, ArrayError>;
}

impl MatmulExt for DenseArray {
    fn matmul(&self, other: &DenseArray) -> Result<DenseArray, ArrayError> {
        let (m, k) = mat_dims(self)?;
        let result_labels = matmul_labels(self, other)?;
        match other.shape().dims() {
            [k2, n] if *k2 == k => Ok(mat_mat(self, other, m, k, *n, result_labels)?),
            [k2] if *k2 == k => Ok(mat_vec(self, other, m, k, result_labels)?),
            _ => Err(ArrayError::ShapeMismatch {
                source: k,
                target: other.shape().dims().first().copied().unwrap_or(0),
            }),
        }
    }
}

fn mat_dims(a: &DenseArray) -> Result<(usize, usize), ArrayError> {
    match a.shape().dims() {
        [m, k] => Ok((*m, *k)),
        _ => Err(ArrayError::RankMismatch {
            expected: 2,
            got: a.rank(),
        }),
    }
}

fn mat_mat(
    a: &DenseArray,
    b: &DenseArray,
    m: usize,
    k: usize,
    n: usize,
    labels: Option<Vec<Option<String>>>,
) -> Result<DenseArray, ArrayError> {
    let data: Vec<f64> = a
        .data()
        .chunks(k)
        .flat_map(|row| {
            (0..n).map(move |j| {
                row.iter()
                    .zip(b.data().chunks(n).map(|col| col[j]))
                    .map(|(x, y)| x * y)
                    .sum::<f64>()
            })
        })
        .collect();
    let arr = DenseArray::new(Shape::new(vec![m, n]), data)?;
    apply_labels(arr, labels)
}

fn mat_vec(
    a: &DenseArray,
    b: &DenseArray,
    m: usize,
    k: usize,
    labels: Option<Vec<Option<String>>>,
) -> Result<DenseArray, ArrayError> {
    let data: Vec<f64> = a
        .data()
        .chunks(k)
        .map(|row| row.iter().zip(b.data().iter()).map(|(x, y)| x * y).sum())
        .collect();
    let _ = m;
    let arr = DenseArray::new(Shape::vector(data.len()), data)?;
    apply_labels(arr, labels)
}

fn apply_labels(
    arr: DenseArray,
    labels: Option<Vec<Option<String>>>,
) -> Result<DenseArray, ArrayError> {
    match labels {
        Some(lbls) => arr.with_labels(lbls),
        None => Ok(arr),
    }
}

