11	impl DenseArray {
12	    /// Saga 29 step 005: ViT patch embedding rearrangement.
13	    /// Take a `[B, C, H, W]` image batch and a square patch
14	    /// size `P` (which must divide both `H` and `W`). Return
15	    /// `[B, N, P*P*C]` where `N = (H/P) * (W/P)` and each
16	    /// row of the trailing axis is one patch flattened with
17	    /// channel-outer order: index `c * P*P + dy * P + dx`.
18	    ///
19	    /// Patch traversal order across `N` is row-major:
20	    /// `n = i * (W/P) + j` for patch row `i` (top-to-bottom)
21	    /// and column `j` (left-to-right).
22	    pub fn patchify(&self, patch_size: usize) -> Result<DenseArray, ArrayError> {
23	        let dims = self.shape().dims();
24	        if dims.len() != 4 {
25	            return Err(ArrayError::ShapeMismatch {
26	                source: dims.len(),
27	                target: 4,
28	            });
29	        }
30	        let (b, c, h, w) = (dims[0], dims[1], dims[2], dims[3]);
31	        if patch_size == 0 || h % patch_size != 0 || w % patch_size != 0 {
32	            return Err(ArrayError::ShapeMismatch {
33	                source: patch_size,
34	                target: h.min(w),
35	            });
36	        }
37	        let p = patch_size;
38	        let nh = h / p;
39	        let nw = w / p;
40	        let n_patches = nh * nw;
41	        let patch_len = p * p * c;
42	        let mut out = vec![0.0; b * n_patches * patch_len];
43	        let src = self.data();
44	        for b_i in 0..b {
45	            for i in 0..nh {
46	                for j in 0..nw {
47	                    let n = i * nw + j;
48	                    for c_i in 0..c {
49	                        for dy in 0..p {
50	                            for dx in 0..p {
51	                                let src_y = i * p + dy;
52	                                let src_x = j * p + dx;
53	                                let src_idx = ((b_i * c + c_i) * h + src_y) * w + src_x;
54	                                let dst_idx =
55	                                    (b_i * n_patches + n) * patch_len + c_i * p * p + dy * p + dx;
56	                                out[dst_idx] = src[src_idx];
57	                            }
58	                        }
59	                    }
60	                }
61	            }
62	        }
63	        DenseArray::new(Shape::new(vec![b, n_patches, patch_len]), out)
64	    }
