use mlpl_array::{ArrayError, DenseArray, Shape};

/// Patchify extension for `DenseArray` (ViT patch embedding rearrangement).
pub trait PatchifyExt {
    /// Take a `[B, C, H, W]` image batch and a square patch size `P`
    /// (which must divide both `H` and `W`). Return `[B, N, P*P*C]`
    /// where `N = (H/P) * (W/P)` and each row of the trailing axis is
    /// one patch flattened with channel-outer order:
    /// `c * P*P + dy * P + dx`.
    fn patchify(&self, patch_size: usize) -> Result<DenseArray, ArrayError>;
}

struct Params {
    b: usize,
    c: usize,
    h: usize,
    w: usize,
    p: usize,
    nh: usize,
    nw: usize,
    n_patches: usize,
    patch_len: usize,
}

impl PatchifyExt for DenseArray {
    fn patchify(&self, patch_size: usize) -> Result<DenseArray, ArrayError> {
        let p = validate(self, patch_size)?;
        let out = compute(self.data(), &p);
        DenseArray::new(Shape::new(vec![p.b, p.n_patches, p.patch_len]), out)
    }
}

fn validate(a: &DenseArray, patch_size: usize) -> Result<Params, ArrayError> {
    let dims = a.shape().dims();
    if dims.len() != 4 {
        return Err(ArrayError::ShapeMismatch {
            source: dims.len(),
            target: 4,
        });
    }
    let (b, c, h, w) = (dims[0], dims[1], dims[2], dims[3]);
    if patch_size == 0 || h % patch_size != 0 || w % patch_size != 0 {
        return Err(ArrayError::ShapeMismatch {
            source: patch_size,
            target: h.min(w),
        });
    }
    let (nh, nw) = (h / patch_size, w / patch_size);
    Ok(Params {
        b,
        c,
        h,
        w,
        p: patch_size,
        nh,
        nw,
        n_patches: nh * nw,
        patch_len: patch_size * patch_size * c,
    })
}

fn compute(src: &[f64], p: &Params) -> Vec<f64> {
    let mut out = vec![0.0; p.b * p.n_patches * p.patch_len];
    for b_i in 0..p.b {
        for i in 0..p.nh {
            for j in 0..p.nw {
                let n = i * p.nw + j;
                copy_patch(src, &mut out, p, b_i, i, j, n);
            }
        }
    }
    out
}

fn copy_patch(
    src: &[f64],
    out: &mut [f64],
    p: &Params,
    b_i: usize,
    i: usize,
    j: usize,
    n: usize,
) {
    for c_i in 0..p.c {
        for dy in 0..p.p {
            for dx in 0..p.p {
