        }
        let b = self.bytes[self.pos];
        if b == b'\n' {
            return Ok(self.make_tok(TokenKind::Newline, self.pos + 1, false));
        }
        if let Some((kind, end)) = lex_builtin_ref(self.bytes, self.pos) {
            return Ok(self.make_tok(kind, end, true));
        }
        if let Some(kind) = single_char_token(b) {
            let is_val = matches!(kind, TokenKind::RParen | TokenKind::RBracket);
            return Ok(self.make_tok(kind, self.pos + 1, is_val));
        }
        if b == b'"' {
            let (kind, end) = lex_string(self.bytes, self.pos)?;
            return Ok(self.make_tok(kind, end, true));
        }
        if b == b'-' {
            return self.lex_minus();
        }
        if b.is_ascii_digit() {
            return self.lex_digit();
        }
        if b.is_ascii_alphabetic() || b == b'_' {
            return Ok(self.lex_ident());
        }
        let ch = self.source[self.pos..].chars().next().unwrap();
        Err(ParseError::UnexpectedCharacter {
            ch,
            span: Span::new(self.pos, self.pos + ch.len_utf8()),
        })
    }

    fn lex_minus(&mut self) -> Result<Token, ParseError> {
        if let Some((tok, end)) = lex_number(self.bytes, self.pos).filter(|_| !self.prev_was_value)
        {
            let span = Span::new(self.pos, end);
            self.pos = end;
            self.prev_was_value = true;
            return Ok(Token { kind: tok, span });
        }
        let tok = Token {
            kind: TokenKind::Minus,
            span: Span::new(self.pos, self.pos + 1),
        };
        self.pos += 1;
        self.prev_was_value = false;
        Ok(tok)
    }

    fn lex_digit(&mut self) -> Result<Token, ParseError> {
        if let Some((tok, end)) = lex_number(self.bytes, self.pos) {
            let span = Span::new(self.pos, end);
            self.pos = end;
            self.prev_was_value = true;
            return Ok(Token { kind: tok, span });
        }
        Err(ParseError::InvalidNumber {
            span: Span::new(self.pos, self.pos + 1),
        })
    }

    fn lex_ident(&mut self) -> Token {
        let start = self.pos;
        while self.pos < self.bytes.len()
            && (self.bytes[self.pos].is_ascii_alphanumeric() || self.bytes[self.pos] == b'_')
        {
            self.pos += 1;
        }
        let name = std::str::from_utf8(&self.bytes[start..self.pos])
            .unwrap()
            .to_owned();
        let kind = match name.as_str() {
            "repeat" => TokenKind::Repeat,
            "train" => TokenKind::Train,
            "for" => TokenKind::For,
            "in" => TokenKind::In,
            "experiment" => TokenKind::Experiment,
            "device" => TokenKind::Device,
            "if" => TokenKind::If,
            "else" => TokenKind::Else,
            "while" => TokenKind::While,
            "break" => TokenKind::Break,
            "continue" => TokenKind::Continue,
            "def" => TokenKind::Def,
            "return" => TokenKind::Return,
            _ => TokenKind::Ident(name),
        };
        self.prev_was_value = matches!(kind, TokenKind::Ident(_));
        Token {
            kind,
            span: Span::new(start, self.pos),
        }
    }
