        NodeKind::Binary { op, left, right } => prop_binary(tape, left, right, op, &upstream),
        NodeKind::SumAll { parent } => prop_sum_mean(tape, parent, &upstream, false),
        NodeKind::MeanAll { parent } => prop_sum_mean(tape, parent, &upstream, true),
