71	/// Classify one submitted line: `:clear` / `:3d ...` / upload commands
72	/// run immediately; everything else is queued for the WASM evaluator.
73	fn classify_line(
74	    deps: &EvalDeps,
75	    line: String,
76	    new_history: &mut Vec<HistoryEntry>,
77	    new_cmds: &mut Vec<String>,
78	    eval_queue: &mut Vec<String>,
79	) {
80	    let trimmed = line.trim();
81	    if trimmed.is_empty() {
82	        return;
83	    }
84	    new_cmds.push(trimmed.to_string());
85	    if trimmed == ":clear" {
86	        deps.session.borrow().clear();
87	        new_history.clear();
88	        if *deps.show_3d {
89	            let _ = js_sys::eval("window.__stage3d_clear && window.__stage3d_clear()");
90	        }
91	        return;
92	    }
93	    if let Some(cmd) = crate::viz3d_toggle::parse_3d_command(trimmed) {
94	        apply_3d_command(deps, cmd);
95	        return;
96	    }
97	    if let Some(name) = parse_upload_command(trimmed) {
98	        new_history.push(handle_upload_command(deps, trimmed, &name));
99	        return;
100	    }
101	    eval_queue.push(trimmed.to_string());
102	}
