115	/// Saga 29 step 018: recursive Timeout-yielding eval loop for
116	/// REPL submissions. Pushes a Running marker, yields, evals,
117	/// replaces marker with result, recurses to next line.
118	fn process_next_eval(
119	    deps: EvalDeps,
120	    mut history: Vec<HistoryEntry>,
121	    queue: Vec<String>,
122	    idx: usize,
123	) {
124	    if idx >= queue.len() {
125	        deps.history.set(history);
126	        return;
127	    }
128	    let line = queue[idx].clone();
129	    push_running_marker(&mut history, &line);
130	    deps.history.set(history.clone());
131	    let deps_next = deps.clone();
132	    let queue_next = queue.clone();
133	    gloo::timers::callback::Timeout::new(0, move || {
134	        let entry = eval_one_line_with_3d(&deps_next, &line);
135	        history.pop();
136	        history.push(entry);
137	        process_next_eval(deps_next, history, queue_next, idx + 1);
138	    })
