fn eval_input_with_values(input: &str, env: &mut Environment) -> EvalResult {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return EvalResult {
            display: String::new(),
            values: None,
            shape: vec![],
        };
    }
    if let Some(out) = mlpl_eval::inspect(env, trimmed) {
        return EvalResult {
            display: out,
            values: None,
            shape: vec![],
        };
    }
    let tokens = match mlpl_parser::lex(trimmed) {
        Ok(t) => t,
        Err(e) => {
            return EvalResult {
                display: format!("error: {e}"),
                values: None,
                shape: vec![],
            };
        }
    };
    let stmts = match mlpl_parser::parse(&tokens) {
        Ok(s) if s.is_empty() => {
            return EvalResult {
                display: String::new(),
                values: None,
                shape: vec![],
            };
        }
        Ok(s) => s,
        Err(e) => {
            return EvalResult {
                display: format!("error: {e}"),
                values: None,
                shape: vec![],
            };
        }
