        click_before: "[data-tour-target='path-card-first']",
    },
    TourStep {
        target: "path-open-lesson",
        title: "Open a Lesson from a Path",
        body: "Click this button to open the lesson in the Tutorial pane. The path remembers where you are.",
        click_before: "",
